import fs from 'node:fs';
import * as T from '../../../packages/actors-bear/three.js';
export {T};
export const jsonLoader=async url=>JSON.parse(fs.readFileSync(new URL(url),'utf8'));
export function textureLoader(){return async()=>{const texture=new T.DataTexture(new Uint8Array(4*4*4).fill(255),4,4);texture.userData.paintValidity=new Uint8Array(16).fill(255);texture.needsUpdate=true;return texture;};}
export function fakeRenderer(){let target=null,color=new T.Color(.12,.24,.36),alpha=.8,viewport=new T.Vector4(1,2,3,4),scissor=new T.Vector4(5,6,7,8),test=true;return {outputColorSpace:T.SRGBColorSpace,toneMapping:T.ACESFilmicToneMapping,capabilities:{getMaxAnisotropy:()=>8},getRenderTarget:()=>target,setRenderTarget:value=>target=value,getClearColor:value=>value.copy(color),getClearAlpha:()=>alpha,setClearColor(value,a){color.set(value);alpha=a;},getViewport:value=>value.copy(viewport),setViewport(...args){viewport=args[0]?.isVector4?args[0].clone():new T.Vector4(...args);},getScissor:value=>value.copy(scissor),setScissor(...args){scissor=args[0]?.isVector4?args[0].clone():new T.Vector4(...args);},getScissorTest:()=>test,setScissorTest:value=>test=value,getPixelRatio:()=>2,clear(){},render(){},snapshot(){return {target,color:color.toArray(),alpha,viewport:viewport.toArray(),scissor:scissor.toArray(),test,space:this.outputColorSpace,tone:this.toneMapping};}};}
